-- Client signups (metadata propai_account_type = 'client') do not get an
-- auto-created broker workspace. All other signups behave as before.
CREATE OR REPLACE FUNCTION public.handle_new_user_personal_org() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'auth', 'pg_temp' AS $function$ declare v_display text; v_slug_base text; v_slug text; v_org_id uuid; v_owner_role_id bigint; v_existing_count integer; begin if coalesce(new.raw_user_meta_data ->> 'propai_account_type', '') = 'client' then return new; end if; v_display := coalesce( nullif(new.raw_user_meta_data ->> 'workspace_name', ''), nullif(new.raw_user_meta_data ->> 'agency_name', ''), nullif(new.raw_user_meta_data ->> 'company_name', ''), nullif(new.raw_user_meta_data ->> 'organization_name', ''), nullif(new.raw_user_meta_data ->> 'full_name', ''), split_part(coalesce(new.email, 'workspace'), '@', 1) ); v_slug_base := lower(regexp_replace(coalesce(v_display, ''), '[^a-zA-Z0-9]+', '-', 'g')); v_slug_base := trim(both '-' from v_slug_base); if v_slug_base = '' or length(v_slug_base) > 40 then v_slug_base := 'workspace-' || substr(replace(new.id::text, '-', ''), 1, 40); end if; v_slug := v_slug_base; while exists (select 1 from public.organizations where slug = v_slug) loop v_slug := v_slug_base || '-' || substr(replace(new.id::text, '-', ''), 1, 6); exit when v_slug = v_slug_base; end loop; select count(*) into v_existing_count from public.organization_members where user_id = new.id and is_active = true; if v_existing_count > 0 then return new; end if; insert into public.organizations (name, slug, subscription_tier, is_active) values (v_display, v_slug, 'trial', true) returning id into v_org_id; select min(id) into v_owner_role_id from public.roles where slug = 'owner' and organization_id is null; if v_owner_role_id is not null then insert into public.organization_members (organization_id, user_id, role_id, is_active) values (v_org_id, new.id, v_owner_role_id, true); else insert into public.organization_members (organization_id, user_id, is_active) values (v_org_id, new.id, true); end if; return new; end; $function$;
